import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"编译加速","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_acceleration"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_acceleration.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_acceleration.md","outlineHeaders":[{"level":2,"title":"ccache编译缓存","slug":"ccache编译缓存","link":"#ccache编译缓存"},{"level":3,"title":"单机ccache","slug":"单机ccache","link":"#单机ccache"},{"level":4,"title":"启用方式","slug":"启用方式","link":"#启用方式"},{"level":4,"title":"验证缓存是否生效","slug":"验证缓存是否生效","link":"#验证缓存是否生效"},{"level":3,"title":"分布式缓存（ccache + Redis）","slug":"分布式缓存（ccache-+-Redis）","link":"#分布式缓存（ccache-+-Redis）"},{"level":2,"title":"选择性编译","slug":"选择性编译","link":"#选择性编译"},{"level":3,"title":"TilingKey选择编译","slug":"TilingKey选择编译","link":"#TilingKey选择编译"},{"level":3,"title":"模板参数选择编译","slug":"模板参数选择编译","link":"#模板参数选择编译"},{"level":3,"title":"收窄芯片范围","slug":"收窄芯片范围","link":"#收窄芯片范围"},{"level":3,"title":"跳过核函数（Kernel）二进制编译","slug":"跳过核函数（Kernel）二进制编译","link":"#跳过核函数（Kernel）二进制编译"},{"level":2,"title":"并行度控制","slug":"并行度控制","link":"#并行度控制"},{"level":2,"title":"增量编译","slug":"增量编译","link":"#增量编译"}],"lastUpdated":1788139350000}'),l={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_acceleration.md"};function e(t,s,d,o,i,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>编译加速</h1><p>本文是扩展内容，介绍如何降低算子工程的编译耗时。算子工程编译耗时主要来自核函数（Kernel）侧代码的逐芯片、逐TilingKey编译；本文从缓存复用、选择性编译、并行度和增量构建四个维度给出加速方案。</p><h2 id="ccache编译缓存">ccache编译缓存<a class="header-anchor" href="#ccache编译缓存">​</a></h2><p>ccache是编译缓存工具。第一次编译时，它把编译结果写入缓存；后续编译如果源码、编译命令、编译器等输入一致，就可以复用缓存，减少重复编译耗时。</p><p>在算子工程中，可通过CMake的<code>CMAKE_CXX_COMPILER_LAUNCHER</code>配置ccache。该变量会作用于Host侧C++编译；在CANN算子工程中，CMake模块也会将ccache路径传给核函数（Kernel）侧编译脚本，用于Ascend C核函数（Kernel）编译过程。</p><h3 id="单机ccache">单机ccache<a class="header-anchor" href="#单机ccache">​</a></h3><p>ccache安装及查找路径命令如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>apt<span class="w"> </span>install<span class="w"> </span>ccache
<span class="nb">command</span><span class="w"> </span>-v<span class="w"> </span>ccache
ccache<span class="w"> </span>--version
</code></pre></div><p>后续配置中的ccache路径以<code>command -v ccache</code>输出为准。ccache清空命令如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ccache<span class="w"> </span>-z<span class="w">          </span><span class="c1">#仅清空统计，不删除缓存内容</span>
ccache<span class="w"> </span>-C<span class="w">          </span><span class="c1">#仅清空缓存内容，不清空统计</span>
ccache<span class="w"> </span>-Cz<span class="w">         </span><span class="c1">#同时清空缓存内容和统计</span>
</code></pre></div><h4 id="启用方式">启用方式<a class="header-anchor" href="#启用方式">​</a></h4><p><strong>命令行临时启用</strong></p><p>开发调试时，推荐在CMake配置阶段通过命令行启用ccache，不需要修改工程文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DCMAKE_CXX_COMPILER_LAUNCHER<span class="o">=</span><span class="k">$(</span><span class="nb">command</span><span class="w"> </span>-v<span class="w"> </span>ccache<span class="k">)</span>
</code></pre></div><p>该命令会把ccache配置写入<code>build_out/CMakeCache.txt</code>。后续继续使用同一个<code>build_out</code>构建目录时，会沿用这个配置。</p><p><strong>写入顶层CMakeLists.txt</strong></p><p>如果希望工程长期默认启用ccache，也可以写入算子工程的顶层<code>CMakeLists.txt</code>，并放在创建编译目标之前，例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">cmake_minimum_required</span><span class="p">(</span><span class="s">VERSION</span><span class="w"> </span><span class="s">3.19.0</span><span class="p">)</span>
<span class="nb">project</span><span class="p">(</span><span class="s">opp</span><span class="p">)</span>

<span class="nb">set</span><span class="p">(</span><span class="s">CMAKE_CXX_COMPILER_LAUNCHER</span><span class="w"> </span><span class="s">/usr/bin/ccache</span><span class="p">)</span>
</code></pre></div><p>如果ccache安装在其他路径，请将<code>/usr/bin/ccache</code>替换为<code>command -v ccache</code>查到的实际路径。</p><h4 id="验证缓存是否生效">验证缓存是否生效<a class="header-anchor" href="#验证缓存是否生效">​</a></h4><p>验证时需要注意：第一次构建通常是写缓存，命中率不高；第二次触发重新编译时，才应该看到缓存命中。</p><p><strong>步骤1：清空缓存和统计，执行第一次构建。</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ccache<span class="w"> </span>-Cz
cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DCMAKE_CXX_COMPILER_LAUNCHER<span class="o">=</span><span class="k">$(</span><span class="nb">command</span><span class="w"> </span>-v<span class="w"> </span>ccache<span class="k">)</span>
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
ccache<span class="w"> </span>--show-stats<span class="w"> </span>-v
</code></pre></div><p>第一次构建后，<code>Misses</code>通常较多，这是正常现象，表示缓存正在写入。</p><p><strong>步骤2：保留缓存，只清空统计，再触发第二次编译。</strong></p><p>如果源码没有变化而直接重复执行<code>cmake --build</code>，CMake可能判断无需重新编译，此时ccache统计不会明显变化。因此验证命中率时，可先执行<code>clean</code>目标清理构建产物，再重新构建：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ccache<span class="w"> </span>-z
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>clean
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
ccache<span class="w"> </span>--show-stats<span class="w"> </span>-v
</code></pre></div><p>第二次构建后，<code>Hits</code>或<code>Primary storage</code>中的<code>Hits</code>应明显提升。如果仍然没有命中，优先检查：</p><ul><li>configure阶段是否传入了<code>-DCMAKE_CXX_COMPILER_LAUNCHER=$(command -v ccache)</code>。</li><li>构建目录中的编译命令是否包含ccache，可搜索<code>build_out</code>下的<code>build.make</code>。</li><li>两次编译的源码、编译器和编译选项是否一致。</li></ul><p>更多<code>ccache</code>配置和缓存行为说明请参考<a href="https://ccache.dev/documentation.html">ccache官方文档</a>。</p><h3 id="分布式缓存（ccache-+-Redis）">分布式缓存（ccache + Redis）<a class="header-anchor" href="#分布式缓存（ccache-+-Redis）">​</a></h3><p>适用于多机共享缓存场景：机器A编译后将结果推送至Redis，机器B在相同源码、相同编译选项和相同工具链版本下可从Redis命中缓存，减少重复编译。</p><p>分布式场景下，<code>ccache</code>以各机器本地缓存作为一级缓存，Redis作为共享二级缓存。机器A首次编译时会调用实际编译器并将结果写入本地缓存和Redis；机器B在相同源码、相同编译命令、相同编译器和相同构建目录路径下再次编译时，可直接从Redis命中共享缓存，减少编译动作的重复执行。若两台机器编译器路径不同但内容一致，建议设置<code>compiler_check=content</code>。</p><p>组网要求：</p><ul><li>机器A：首次编译机器，将缓存写入Redis，IP为<code>&lt;A_IP&gt;</code></li><li>机器B：二次编译机器，从Redis验证共享缓存命中，IP为<code>&lt;B_IP&gt;</code></li><li>机器C：Redis服务器，保存共享缓存数据，IP为<code>&lt;C_IP&gt;</code></li><li>A、B、C三台机器需处于同一网络下，A/B机器都必须能够访问<code>C_IP:6379</code></li></ul><p>建议机器A和机器B使用相同的源码内容、相同的编译命令、相同版本的编译器，并保持一致的源码路径和构建目录路径，否则可能出现缓存未命中的情况。</p><p><strong>1. 机器C：部署Redis服务</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>apt<span class="w"> </span>install<span class="w"> </span>redis-server
<span class="c1"># 启动Redis服务</span>
redis-server<span class="w"> </span>--daemonize<span class="w"> </span>yes<span class="w"> </span>--bind<span class="w"> </span><span class="m">0</span>.0.0.0<span class="w"> </span>--port<span class="w"> </span><span class="m">6379</span><span class="w"> </span>--requirepass<span class="w"> </span>&lt;PASSWORD&gt;
<span class="c1"># 验证Redis连接</span>
redis-cli<span class="w"> </span>-h<span class="w"> </span>&lt;C_IP&gt;<span class="w"> </span>-p<span class="w"> </span><span class="m">6379</span><span class="w"> </span>-a<span class="w"> </span>&lt;PASSWORD&gt;<span class="w"> </span>ping
</code></pre></div><blockquote><p>说明：上述配置仅用于受控测试环境。共享环境或生产环境建议开启访问控制、认证和网络隔离。</p></blockquote><p><strong>2. 机器A / 机器B：配置ccache</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>apt<span class="w"> </span>install<span class="w"> </span>redis-tools
<span class="c1"># 验证Redis连接</span>
redis-cli<span class="w"> </span>-h<span class="w"> </span>&lt;C_IP&gt;<span class="w"> </span>-p<span class="w"> </span><span class="m">6379</span><span class="w"> </span>-a<span class="w"> </span>&lt;PASSWORD&gt;<span class="w"> </span>ping
<span class="c1"># 配置Redis作为二级存储，带密码认证格式</span>
<span class="c1"># 格式：redis://default:&lt;PASSWORD&gt;@&lt;C_IP&gt;:6379</span>
ccache<span class="w"> </span>--set-config<span class="o">=</span><span class="nv">secondary_storage</span><span class="o">=</span>redis://default:&lt;PASSWORD&gt;@&lt;C_IP&gt;:6379
<span class="c1"># 配置编译器内容校验，避免路径差异导致缓存未命中</span>
ccache<span class="w"> </span>--set-config<span class="o">=</span><span class="nv">compiler_check</span><span class="o">=</span>content
</code></pre></div><p><strong>3. 机器A / 机器B：执行构建</strong></p><p>机器A构建会写入本地缓存和Redis:</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ccache<span class="w"> </span>-Cz
cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DCMAKE_CXX_COMPILER_LAUNCHER<span class="o">=</span><span class="k">$(</span><span class="nb">command</span><span class="w"> </span>-v<span class="w"> </span>ccache<span class="k">)</span>
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
ccache<span class="w"> </span>--show-stats<span class="w"> </span>-v
</code></pre></div><p>机器B本地缓存为空，可从Redis读取共享缓存。机器A构建后，在机器B上执行构建:</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ccache<span class="w"> </span>-z
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>clean
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
ccache<span class="w"> </span>--show-stats<span class="w"> </span>-v
</code></pre></div><p>对比两次<code>ccache --show-stats -v</code>结果，可看到在机器B上远程缓存命中率<code>Remote storage Hits</code>显著提升。</p><p><a id="选择性编译"></a></p><h2 id="选择性编译">选择性编译<a class="header-anchor" href="#选择性编译">​</a></h2><p>选择性编译的核心思路是：开发调试阶段只编译当前真正需要验证的部分，减少无关核函数（Kernel）变体、无关芯片和无关产物带来的编译开销。常用策略如下：</p><table><thead><tr><th>策略</th><th>适用场景</th><th>配置方式</th><th>效果</th></tr></thead><tbody><tr><td><code>--tiling_key=1,2</code></td><td>TilingKey编程算子，仅调试特定分支。</td><td><code>npu_op_kernel_options</code>的OPTIONS参数。</td><td>只编译指定TilingKey的核函数（Kernel），跳过其余。</td></tr><tr><td><code>--kernel-template-input=&quot;D_T_X=float&quot;</code></td><td>模板编程算子，仅调试特定模板参数组合。</td><td><code>npu_op_kernel_options</code>的OPTIONS参数。</td><td>只编译指定模板参数组合的核函数（Kernel）。</td></tr><tr><td><code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>收窄</td><td>开发阶段只跑当前SOC。</td><td>修改<code>CMakePresets.json</code>或CMake配置参数；两者二选一。</td><td>跳过其他芯片的核函数（Kernel）编译。</td></tr><tr><td><code>ENABLE_BINARY_PACKAGE=False</code></td><td>源码发布模式，不需要核函数（Kernel）二进制。</td><td>CMakeLists.txt或cmake参数。</td><td>跳过核函数（Kernel） <code>.o</code>生成，保留核函数（Kernel）源码和必要配置。</td></tr></tbody></table><h3 id="TilingKey选择编译">TilingKey选择编译<a class="header-anchor" href="#TilingKey选择编译">​</a></h3><p>只编译指定<a href="../design_and_implementation/multi_branch_strategy.html#compile-selected-tiling-keys">TilingKey</a>相关的核函数（Kernel）代码，用于加速编译过程。若不指定TilingKey编译，则默认编译所有的TilingKey。配置多个TilingKey时，TilingKey之间不能有空格。示例如下，其中1、2为TilingKey取值：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 在op_kernel/CMakeLists.txt中添加</span>
npu_op_kernel_options<span class="o">(</span>ascendc_kernels<span class="w"> </span>AddCustom<span class="w"> </span>COMPUTE_UNIT<span class="w"> </span>Ascendxxyy<span class="w"> </span>OPTIONS<span class="w"> </span>--tiling_key<span class="o">=</span><span class="m">1</span>,2<span class="o">)</span>
</code></pre></div><h3 id="模板参数选择编译">模板参数选择编译<a class="header-anchor" href="#模板参数选择编译">​</a></h3><p>对于多分支与模板化算子，可只编译指定的模板参数组合。设置<code>--kernel-template-input</code>选项后，只编译指定的模板参数组合相关的核函数（Kernel）代码，用于加速编译过程。若不设置该选项，则默认编译所有的模板参数组合。传入的参数为键值对列表，整体需用双引号或单引号包裹。不同模板参数之间用英文分号（;）分隔，相同模板参数配置多个值时用英文逗号（,）分隔。配置时不能有空格。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>npu_op_kernel_options<span class="o">(</span>ascendc_kernels<span class="w"> </span>AddCustomTemplate<span class="w"> </span>COMPUTE_UNIT<span class="w"> </span>Ascendxxyy<span class="w"> </span>OPTIONS<span class="w"> </span>--kernel-template-input<span class="o">=</span><span class="s2">&quot;D_T_X=float;D_T_Y=float;D_T_Z=float&quot;</span><span class="o">)</span>
</code></pre></div><p>配置模板参数组合时，模板参数名需要与核函数（Kernel）入口处以及Host侧定义的模板参数名匹配。对于模板参数组合的值，如果存在自定义类型，需要替换为其对应数字值，如果为原生支持数据类型，则与核函数（Kernel）入口处入参保持一致。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Host侧模板参数定义</span>
<span class="cp">#define ADD_TPL_FP16 10</span>
<span class="cp">#define ADD_TPL_FP32 20</span>

<span class="n">ASCENDC_TPL_ARGS_DECL</span><span class="p">(</span><span class="n">AddCustomTemplateNativeDtype</span><span class="p">,</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_DECL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_INPUT</span><span class="p">(</span><span class="mi">0</span><span class="p">)),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DTYPE_DECL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">ADD_TPL_FP16</span><span class="p">,</span><span class="w"> </span><span class="n">ADD_TPL_FP32</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_DECL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_OUTPUT</span><span class="p">(</span><span class="mi">0</span><span class="p">)),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_UINT_DECL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_8_BW</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_MIX</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span><span class="w"> </span><span class="mi">10</span><span class="p">,</span><span class="w"> </span><span class="mi">12</span><span class="p">,</span><span class="w"> </span><span class="mi">13</span><span class="p">,</span><span class="w"> </span><span class="mi">9</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_BOOL_DECL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="p">);</span>

<span class="n">ASCENDC_TPL_SEL</span><span class="p">(</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DTYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">ADD_TPL_FP32</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DETERMINISTIC_SEL</span><span class="p">(</span><span class="nb">true</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_KERNEL_TYPE_SEL</span><span class="p">(</span><span class="n">ASCENDC_TPL_AIV_ONLY</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DTYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">ADD_TPL_FP16</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DETERMINISTIC_SEL</span><span class="p">(</span><span class="nb">false</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_KERNEL_TYPE_SEL</span><span class="p">(</span><span class="n">ASCENDC_TPL_AIV_ONLY</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="p">);</span>
<span class="cp">#endif</span>

<span class="c1">// 核函数（Kernel）入口。模板参数名需要与Host侧模板参数定义保持一致。</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">IS_SPLIT</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom_template</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                                               </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tiling_data</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">std</span><span class="o">::</span><span class="n">is_same_v</span><span class="o">&lt;</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">is_same_v</span><span class="o">&lt;</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">KernelAdd</span><span class="o">&lt;</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">D_T_Z</span><span class="o">&gt;</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">tiling_data</span><span class="p">.</span><span class="n">totalLength</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">);</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">Process1</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">std</span><span class="o">::</span><span class="n">is_same_v</span><span class="o">&lt;</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">is_same_v</span><span class="o">&lt;</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">KernelAdd</span><span class="o">&lt;</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">D_T_Z</span><span class="o">&gt;</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">tiling_data</span><span class="p">.</span><span class="n">totalLength</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">);</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">Process2</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>编译选项示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>npu_op_kernel_options<span class="o">(</span>ascendc_kernels<span class="w"> </span>AddCustomTemplate<span class="w"> </span>COMPUTE_UNIT<span class="w"> </span>Ascendxxyy<span class="w"> </span>OPTIONS<span class="w"> </span>--kernel-template-input<span class="o">=</span><span class="s2">&quot;D_T_X=half;D_T_Y=10;D_T_Z=half&quot;</span><span class="o">)</span>
</code></pre></div><h3 id="收窄芯片范围">收窄芯片范围<a class="header-anchor" href="#收窄芯片范围">​</a></h3><p><code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>配置了多少个芯片型号，核函数（Kernel）侧通常就会按芯片型号分别编译。开发阶段如果只在当前机器上验证，可修改CMakeLists.txt中的任一配置保留当前SOC，或者在CMake配置阶段临时只构建某个SOC。以下示例只构建ascendxxx SOC的示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DASCEND_SOC_SERIES<span class="o">=</span>ascendxxx
</code></pre></div><p>也可以使用参数<code>-DASCEND_COMPUTE_UNIT=ascendxxxyy</code>；两个参数不能同时传入。</p><h3 id="跳过核函数（Kernel）二进制编译">跳过核函数（Kernel）二进制编译<a class="header-anchor" href="#跳过核函数（Kernel）二进制编译">​</a></h3><p>如果当前只需要生成源码包，或暂时不需要核函数（Kernel） <code>.o</code>二进制，可关闭二进制包生成。顶层<code>CMakeLists.txt</code>中应使用变量形式传递<code>ENABLE_BINARY_PACKAGE</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">ENABLE_SOURCE_PACKAGE</span><span class="o">}</span>
<span class="w">        </span><span class="s">ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">ENABLE_BINARY_PACKAGE</span><span class="o">}</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="p">)</span>
</code></pre></div><p>然后在configure阶段关闭二进制编译：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DENABLE_BINARY_PACKAGE<span class="o">=</span>False
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>该模式下仍会执行Host侧库、Tiling库和配置文件生成，但传给核函数（Kernel）编译脚本的<code>--enable-binary</code>为<code>False</code>，不会生成核函数（Kernel） <code>.o</code>二进制文件；<code>op_kernel/ascendc_kernels/binary/dynamic/</code>下会保留核函数（Kernel）源码等文件。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>如果顶层<code>CMakeLists.txt</code>在<code>npu_op_package(... CONFIG ...)</code>中硬编码了<code>ENABLE_BINARY_PACKAGE True</code>，命令行传入的<code>-DENABLE_BINARY_PACKAGE=False</code>不会生效。要允许命令行覆盖，应改为<code>\${ENABLE_BINARY_PACKAGE}</code>变量形式，或不要在CONFIG中覆盖该变量。</p></div><h2 id="并行度控制">并行度控制<a class="header-anchor" href="#并行度控制">​</a></h2><p><code>cmake --build ... -j</code>用来控制构建阶段的并行任务数。合理提高并行度可以缩短编译时间，但线程数过高会带来CPU、内存和I/O资源争抢，严重时反而变慢，甚至触发编译失败。</p><p><strong>线程数选择建议</strong>：</p><ul><li>一般场景可先使用<code>-j$(nproc)</code>，让构建系统按可用CPU核数并行。</li><li>如果机器内存较小，或核函数（Kernel）编译阶段出现明显卡顿、系统负载过高，可改为<code>nproc / 2</code>或固定较小值。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j8
</code></pre></div><h2 id="增量编译">增量编译<a class="header-anchor" href="#增量编译">​</a></h2><p>增量编译指不删除<code>build_out</code>，继续使用同一个构建目录，CMake复用上一次configure生成的构建规则、中间文件和部分已编译产物。避免每次构建都从零开始，加快构建编译速度。</p><p>第一次构建时，需要先执行configure，再执行build：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p><strong>增量编译</strong>：之后如果只是修改已有源码文件，通常只需要重新执行build。Host侧C++文件、Tiling实现等CMake可追踪依赖的目标，一般可以根据文件变更按需触发对应目标重新编译。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p><strong>全量编译</strong>：但是如果修改了工程结构、CMake配置或会影响代码生成的内容，例如修改算子原型、修改CMakeLists.txt配置或者新增/删除算子文件等，需要先重新执行configure，再build：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>大多数源码小改动都不需要清空<code>build_out</code>。只有在怀疑构建目录里残留了错误状态时，才需要重新创建干净的build目录：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>rm<span class="w"> </span>-rf<span class="w"> </span>build_out
cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p><strong>增量编译和ccache</strong>可以配合使用。增量编译减少需要重新处理的目标；当某些文件仍被触发重编时，ccache可以在源码、编译命令和编译器一致的情况下复用缓存：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DCMAKE_CXX_COMPILER_LAUNCHER<span class="o">=</span><span class="k">$(</span><span class="nb">command</span><span class="w"> </span>-v<span class="w"> </span>ccache<span class="k">)</span>
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>后续继续使用同一个<code>build_out</code>时，<code>CMAKE_CXX_COMPILER_LAUNCHER</code>会保存在<code>build_out/CMakeCache.txt</code>中，不需要每次build都重新传入。</p></article></div>`,1)])])}const v=a(l,[["render",e]]);export{w as __pageData,v as default};
